// === Check table state ===
// Mode: "Run Once for All Items". Input = every row currently in cs_high_risk_keywords.
//
// 1) Refuses to run if non-English rows are already in the table, so a second
//    run can never double-import the localized list.
// 2) Collects the existing English keywords (NFC + lowercase, the same way the
//    matcher sees them) so a localized row that is identical to an English
//    keyword is never quarantined - it behaves exactly like the English row.
// 3) Passes the uploaded file on as binary "data" for Extract From File.

function prepare(t) {
  return String(t == null ? '' : t).normalize('NFC').toLowerCase().trim();
}

const rows = $input.all().map(i => i.json || {}).filter(r => r.keyword != null);

const nonEnglish = rows.filter(r => {
  const l = String(r.language == null ? '' : r.language).trim().toLowerCase();
  return l !== '' && l !== 'en';
});
if (nonEnglish.length > 0) {
  throw new Error('cs_high_risk_keywords already holds ' + nonEnglish.length +
    ' non-English rows. Delete them first if you really want to re-import - this guard prevents a double import.');
}

const trig = $('Upload keyword sheet').first();
const bin = trig.binary || {};
const keys = Object.keys(bin);
if (!keys.length) {
  throw new Error('No file was received from the form.');
}

return [{
  json: {
    existing_rows: rows.length,
    existing_keys: Array.from(new Set(rows.map(r => prepare(r.keyword)).filter(Boolean)))
  },
  binary: { data: bin[keys[0]] }
}];

// === Build localized rows ===
// Mode: "Run Once for All Items". Input = one item per row of the sheet
// "All languages" (Extract From File).
//
// Maps the sheet onto cs_high_risk_keywords:
//   Term -> keyword (as written, NFC), Tier -> tier, Category -> category,
//   Language -> language, active true, notes empty.
// Routing and Human handling are NOT imported: they map 1:1 to the tier
// (A = Priority / hot-legal-financial, B = Standard / hot-conduct), which is
// exactly what the matcher's TIER_QUEUE already does.
//
// QUARANTINE. 465 terms were flagged offline (wordfreq, English Zipf >= 3.5)
// because under exact matching they would fire on ordinary ENGLISH tickets:
//   w = single word that is also a common English word (per, love, process, as)
